<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';import {AgentTriggerClient,TriggerError,type AgentTrigger} from './agent-trigger-client';import './automations.css';
 export let companyId:string;export let actorId:string;export let conversationId:string;export let triggerId:string;export let accessSignal:AbortSignal;export let botName='Your bot';
 const dispatch=createEventDispatcher<{close:void;denied:{status:number}}>();
 let mounted=false,key='',watched:AbortSignal|undefined,client:AgentTriggerClient|undefined,trigger:AgentTrigger|null=null,generation=0,busy=false,error='',confirmed=false,testConfirmed=false,session='',element:HTMLElement,visible=false,observer:IntersectionObserver|undefined,timer:ReturnType<typeof setTimeout>|undefined;
 const labels:Record<string,string>={DRAFT:'Review daily automation',ACTIVATING:'Activating',ACTIVE:'Active',PAUSING:'Pausing',PAUSED:'Paused',UNKNOWN:'Outcome uncertain'};
 $: if(mounted&&(key!==[companyId,actorId,conversationId,triggerId].join('\0')||watched!==accessSignal)){reset();key=[companyId,actorId,conversationId,triggerId].join('\0');watched=accessSignal;watched.addEventListener('abort',lost,{once:true});if(watched.aborted)lost();else{session=localStorage.getItem('token')||'';client=new AgentTriggerClient(companyId,conversationId,triggerId,()=>localStorage.getItem('token')||'',watched);void load();}}
 function reset(){generation++;clearTimeout(timer);client?.close();client=undefined;watched?.removeEventListener('abort',lost);trigger=null;confirmed=false;testConfirmed=false;busy=false;error='';}
 function lost(){reset();dispatch('close');}
 function fail(e:unknown){confirmed=false;testConfirmed=false;if(e instanceof TriggerError&&(e.status===401||e.status===403)){lost();dispatch('denied',{status:e.status});return;}error=e instanceof Error?e.message:'The saved automation could not be checked.';}
 function schedule(){clearTimeout(timer);if(!visible||document.hidden||!trigger)return;const delay=['ACTIVATING','PAUSING'].includes(trigger.state)?2000:trigger.state==='ACTIVE'?5000:0;if(delay)timer=setTimeout(()=>void load(),delay);}
 async function load(){if(!client||busy)return;const c=client,n=generation;busy=true;error='';try{const next=await c.get();if(n!==generation)return;if(trigger?.reviewedHash!==next.reviewedHash||trigger?.revision!==next.revision){confirmed=false;testConfirmed=false;}trigger=next;schedule();}catch(e){if(n===generation)fail(e);}finally{if(n===generation)busy=false;}}
 async function act(action:'activate'|'pause'|'resume'|'test'){if(!client||!trigger||busy||(['activate','resume'].includes(action)&&!confirmed)||action==='test'&&!testConfirmed)return;const c=client,n=generation,review=trigger;busy=true;confirmed=false;testConfirmed=false;error='';try{const next=await c.action(action,review);if(n!==generation)return;trigger=next;schedule();}catch(e){if(n===generation){fail(e);trigger=null;}}finally{if(n===generation)busy=false;}}
 function visibility(){if(document.hidden)clearTimeout(timer);else{if(client&&visible)void load();}}
 function storage(e:StorageEvent){if(e.key===null||e.key==='token')lost();}
 onMount(()=>{mounted=true;observer=new IntersectionObserver(entries=>{visible=entries.some(e=>e.isIntersecting);if(visible)schedule();else clearTimeout(timer);});observer.observe(element);document.addEventListener('visibilitychange',visibility);window.addEventListener('storage',storage);const interval=setInterval(()=>{if(client&&session!==(localStorage.getItem('token')||''))lost();},500);return()=>clearInterval(interval);});onDestroy(()=>{reset();observer?.disconnect();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('storage',storage);});
</script>
<section bind:this={element} class="starli-automations trigger-card" aria-label="Automation activation">
 <span class="sa-eyebrow">AUTOMATION ACTIVATION</span><h3>{trigger?labels[trigger.state]:'Checking saved automation…'}</h3>
 {#if error}<p class="sa-error" role="alert">{error}</p>{/if}
 {#if trigger}<h4>{trigger.name}</h4><dl><dt>When</dt><dd>Every day at {trigger.dailyTime} · {trigger.timeZone}</dd><dt>Bot</dt><dd>{botName}</dd><dt>Where</dt><dd>Here in this chat</dd><dt>Ends</dt><dd>{new Date(trigger.expiresAt*1000).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short',timeZone:trigger.timeZone})} · {trigger.timeZone}</dd><dt>Instructions</dt><dd class="prompt">{trigger.prompt}</dd></dl>
 <p class="sa-muted">Each new wake uses this bot’s currently selected provider and model from Agent Settings, along with its current permissions. Changing the model affects future wakes; a running job does not switch models. If the selected model is unavailable or revoked, the wake fails instead of falling back to an older model.</p>
 {#if trigger.state==='DRAFT'&&trigger.actions.canActivate||trigger.state==='PAUSED'&&trigger.actions.canResume}<label class="review"><input type="checkbox" bind:checked={confirmed} disabled={busy}/> I approve this ongoing daily rule, including the bot’s use of its permitted tools.</label><button class="sa-primary" disabled={!confirmed||busy} on:click={()=>act(trigger?.state==='PAUSED'?'resume':'activate')}>{trigger.state==='PAUSED'?'Resume automation':'Activate automation'}</button>{/if}
 {#if trigger.state==='ACTIVE'&&trigger.actions.canPause}<button disabled={busy} on:click={()=>act('pause')}>Pause automation</button>{/if}
 {#if trigger.state==='ACTIVE'&&trigger.actions.canTest}<label class="review"><input type="checkbox" bind:checked={testConfirmed} disabled={busy}/> Wake this bot now with these instructions. It may use its permitted tools.</label><button disabled={!testConfirmed||busy} on:click={()=>act('test')}>Test now</button>{/if}
 {#if trigger.lastEvent?.state}<p role="status">Last event: {trigger.lastEvent.state}</p>{/if}
 {#if trigger.state==='UNKNOWN'}<p role="status">The outcome is uncertain. Refresh the saved status before taking further action.</p>{/if}
 {/if}<button disabled={busy} on:click={()=>void load()}>Refresh status</button>
</section>
<style>.trigger-card{max-width:740px;margin:12px 0;padding:20px;border:1px solid #e6ebf4;border-radius:12px;background:#fafbfd}.trigger-card h3{margin:8px 0}.trigger-card h4{margin:16px 0}.trigger-card dl{margin:12px 0}.trigger-card dt{color:#71809a;font-size:12px;margin-top:12px}.trigger-card dd{margin:4px 0;overflow-wrap:anywhere}.trigger-card .prompt{white-space:pre-wrap;background:#f6f8fc;padding:12px;border-radius:8px}.trigger-card .review{display:flex;gap:10px;align-items:flex-start;margin:16px 0}.trigger-card button{margin:8px 8px 0 0}@media(max-width:500px){.trigger-card{padding:15px;max-width:100%;min-width:0}}</style>
